#!/usr/bin/env python3
"""__DISPLAY_NAME__ — generated by `plexi app init`."""
from plexi_sdk import App, RenderContext
from plexi_sdk.ui import AppBar, Column, FooterKeys, Label


class __CLASS_NAME__(App):
    async def on_init(self, ctx: RenderContext) -> None:
        state = ctx.load_state()
        self.count: int = state.get("count", 0)
        self.running = False

    def on_render(self, ctx: RenderContext) -> None:
        ctx.render(Column([
            AppBar(title="__DISPLAY_NAME__"),
            Label(str(self.count), bold=True),
            FooterKeys([
                ("space", "start/stop"),
                ("+/-", "increment"),
                ("r", "reset"),
                ("esc", "close"),
            ]),
        ]))

    async def on_key(self, ctx: RenderContext, key: str, mods: dict) -> None:
        if key in ("equals", "plus"):
            self.count += 1
        elif key == "minus":
            self.count -= 1
        elif key == "r":
            self.count = 0
        elif key == "space":
            if self.running:
                self.emit.cancel_timer("tick")
                self.running = False
            else:
                self.emit.set_timer("tick", 1000)
                self.running = True
        ctx.save_state({"count": self.count})

    async def on_timer(self, ctx: RenderContext, timer_id: str) -> None:
        if timer_id == "tick":
            self.count += 1
            ctx.save_state({"count": self.count})
            if self.running:
                self.emit.set_timer("tick", 1000)


__CLASS_NAME__().run()
